css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-tk { width: min(680px, 100%); display: flex; flex-direction: column; gap: 22px; }
.bs-tk h3 {
  margin: 0 0 10px; font-family: var(--fonte-titulo); font-size: 13px; font-weight: 600;
  color: var(--text);
}

.bs-tk-grade { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; }
.bs-tk-cor {
  display: flex; flex-direction: column; gap: 6px;
  padding: 12px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-surface);
}
/* A amostra leva a mesma borda dos cards: sem ela, #0a0a0a sobre #111 some. */
.bs-tk-cor span { height: 34px; border-radius: 8px; border: 1px solid var(--border); }
.bs-tk-cor b { font-size: 12px; font-weight: 600; color: var(--text); }
.bs-tk-cor i { font-family: var(--fonte-mono); font-size: 11px; font-style: normal; color: var(--text-muted); }

.bs-tk-tipo {
  display: flex; flex-direction: column; gap: 10px;
  padding: 16px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface);
}
.bs-tk-num {
  font-family: var(--fonte-titulo); font-size: 22px; font-weight: 600;
  letter-spacing: -0.02em; color: var(--text);
}
.bs-tk-titulo { font-family: var(--fonte-titulo); font-size: 15px; font-weight: 600; color: var(--text); }
.bs-tk-corpo { font-size: 13px; color: var(--text-muted); }
.bs-tk-rotulo {
  font-size: 11px; font-weight: 500; text-transform: uppercase;
  letter-spacing: 0.06em; color: var(--text-muted);
}
.bs-tk-mono { font-family: var(--fonte-mono); font-size: 12px; color: var(--text-muted); }
